const app=document.querySelector('#app'),route=location.pathname;let state={token:localStorage.adminToken||sessionStorage.adminToken||'',batch:[]};
const api=async(path,o={})=>{const r=await fetch('/api'+path,{...o,headers:{'Content-Type':'application/json',...(state.token?{Authorization:'Bearer '+state.token}:{}),...(o.headers||{})}}),d=await r.json();if(!r.ok)throw Error(d.error||'Erro');return d};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const fmt=n=>Number(n).toLocaleString('pt-BR'),date=v=>v?new Date(v).toLocaleString('pt-BR'):'—';
function layout(title,content){const f=state.feedback;state.feedback=null;app.innerHTML=`<div class="shell"><header class="top"><div class="brand-wrap"><img class="brand-logo" src="/melodia-logo.png" alt="Melodia Pet"><div><div class="brand-title">Controle de Movimentação</div><div class="small">${title}</div></div></div></header><div id="message">${f?`<div class="notice ${f.error?'error':''}">${esc(f.text)}</div>`:''}</div>${content}</div>`}
function msg(t,b=false){const e=document.querySelector('#message');if(e)e.innerHTML=`<div class="notice ${b?'error':''}">${esc(t)}</div>`}
async function load(){try{if(route==='/admin'){if(!state.token)return adminLogin();Object.assign(state,await api('/bootstrap'));return admin()}Object.assign(state,await api('/public/bootstrap'));route==='/logistica'?logistics():production()}catch(e){sessionStorage.removeItem('adminToken');localStorage.removeItem('adminToken');state.token='';route==='/admin'?adminLogin():msg(e.message,true)}}
function cards(){const s=state.summary;return `<div class="grid"><section class="card span-4"><div class="small">AGUARDANDO TRANSFERÊNCIA</div><div class="metric">${s.pallets}</div><div class="small">paletes prontos na fábrica</div></section><section class="card span-8"><h2>Resumo de Movimentações Pendentes</h2><p><strong>Total: ${s.pallets} palete${s.pallets===1?'':'s'}</strong></p><div class="totals">${s.products.map(x=>`<div class="total"><strong>${esc(x.product)}</strong><br>${fmt(x.quantity)} unidades</div>`).join('')||'<span class="small">Nenhum palete pendente.</span>'}</div></section></div>`}
function table(items,cancel=false){return `<table><thead><tr><th>Produto</th><th>OP</th><th>Quantidade</th><th>Status</th><th>Pronto em</th>${cancel?'<th></th>':''}</tr></thead><tbody>${items.length?items.map(p=>`<tr><td>${esc(p.product)}</td><td>${esc(p.op)}</td><td>${fmt(p.quantity)}</td><td><span class="badge ${p.status==='RECEBIDO'?'received':p.status==='CANCELADO'?'cancelled':''}">${p.status}</span></td><td class="small">${date(p.readyAt)}</td>${cancel?`<td>${p.status==='PRONTO'?`<button class="danger cancel" data-id="${esc(p.id)}">Cancelar</button>`:''}</td>`:''}</tr>`).join(''):'<tr><td colspan="6" class="small">Nenhum registro.</td></tr>'}</tbody></table>`}
function production(){layout('Produção',`${cards()}<div class="grid"><section class="card span-4"><h2>Produção</h2><p class="small">Leia o QR Code da capa.</p><div class="scanner"><button class="accent camera" data-mode="register">Ler QR Code</button><button class="secondary camera" data-mode="partial">Retirar unidades</button></div></section><section class="card span-8"><h2>Pendentes</h2>${table(state.pallets.filter(p=>p.status==='PRONTO'),true)}</section></div>`);bindPublic()}
function logistics(){const pend=state.pallets.filter(p=>p.status==='PRONTO'),chosen=state.batch.map(i=>pend.find(p=>p.id===i)).filter(Boolean);layout('Logística',`${cards()}<div class="grid"><section class="card span-7"><h2>Receber transferência em lote</h2><p class="small">Leia cada QR Code que chegou ao galpão de produto acabado.</p><div class="scanner"><button class="accent camera" data-mode="batch">Ler QR Code</button></div><ul class="scanlist">${chosen.map(p=>`<li>${esc(p.product)} · ${esc(p.op)} · ${fmt(p.quantity)} un.<button class="secondary remove" data-id="${esc(p.id)}">Remover</button></li>`).join('')||'<li class="small">Nenhum palete adicionado.</li>'}</ul></section><section class="card span-5"><h2>Assinatura de recebimento</h2><canvas id="signature" width="700" height="280"></canvas><p><button class="secondary" id="clear">Limpar assinatura</button></p><button id="confirm" ${chosen.length?'':'disabled'}>Confirmar recebimento de ${chosen.length} palete${chosen.length===1?'':'s'}</button></section></div>`);bindPublic();signature()}
function adminLogin(){layout('Administração',`<section class="login"><h1>Acesso administrativo</h1><p class="small">Use a senha administrativa para consultar o relatório e configurar o Discord.</p><form id="adminlogin"><label>Senha<input type="password" name="password" required autofocus></label><button>Entrar</button></form></section>`);document.querySelector('#adminlogin').onsubmit=async e=>{e.preventDefault();try{const d=await api('/login',{method:'POST',body:JSON.stringify({username:'admin',password:new FormData(e.target).get('password')})});state.token=d.token;sessionStorage.adminToken=d.token;load()}catch(x){msg(x.message,true)}}}
function admin(){layout('Administração',`<div class="grid"><section class="card span-12"><h2>Relatório mensal de movimentações</h2><div class="row"><label>Mês<input id="month" type="month" value="${new Date().toISOString().slice(0,7)}"></label><button id="csv">Baixar CSV</button></div><div id="report"></div></section><section class="card span-12"><h2>Configuração do Discord</h2><form id="settings" class="form"><label>Webhook do canal Discord<input name="discordWebhook" value="${esc(state.settings.discordWebhook||'')}" placeholder="https://discord.com/api/webhooks/..." ></label><label>Dias de envio</label><div class="actions">${['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'].map((d,i)=>`<label><input type="checkbox" name="days" value="${i}" ${(state.settings.discordDays||[]).includes(i)?'checked':''}> ${d}</label>`).join('')}</div><label>Horário (24h)<input name="discordHour" type="time" value="${esc(state.settings.discordHour||'18:00')}" required></label><div class="actions"><button>Salvar configuração</button><button class="secondary" type="button" id="test">Enviar teste</button></div></form></section></div>`);report();document.querySelector('#month').onchange=report;document.querySelector('#csv').onclick=csv;document.querySelector('#settings').onsubmit=saveSettings;document.querySelector('#test').onclick=async()=>{try{await api('/admin/test-discord',{method:'POST'});msg('Mensagem de teste enviada.')}catch(e){msg(e.message,true)}}}
function admin(){state.adminView=state.adminView||'relatorio';const tabs=[['relatorio','Relatório'],['registrar','Registrar palete'],['pendentes','Pendentes'],['receber','Receber transferência'],['discord','Discord']];let content='';if(state.adminView==='registrar')content=`<section class="card"><h2>Registrar palete</h2><div class="scanner"><button class="accent camera" data-mode="register">Ler QR Code</button><details><summary class="small">Inserir código manualmente</summary><form id="register" class="form"><input name="code" required><button>Registrar palete</button></form></details></div></section>`;else if(state.adminView==='pendentes')content=`<section class="card"><h2>Paletes pendentes</h2>${table(state.pallets.filter(p=>p.status==='PRONTO'),true)}</section>`;else if(state.adminView==='receber'){const p=state.pallets.filter(x=>x.status==='PRONTO'),c=state.batch.map(i=>p.find(x=>x.id===i)).filter(Boolean);content=`<div class="grid"><section class="card span-7"><h2>Receber transferência</h2><div class="scanner"><button class="accent camera" data-mode="batch">Ler QR Code</button><details><summary class="small">Inserir código manualmente</summary><form id="batch" class="form"><input name="code" required><button>Adicionar</button></form></details></div><ul class="scanlist">${c.map(x=>`<li>${esc(x.product)} · ${fmt(x.quantity)} un.<button class="secondary remove" data-id="${esc(x.id)}">Remover</button></li>`).join('')||'<li class="small">Nenhum palete adicionado.</li>'}</ul></section><section class="card span-5"><h2>Assinatura</h2><canvas id="signature" width="700" height="280"></canvas><p><button class="secondary" id="clear">Limpar assinatura</button></p><button id="confirm" ${c.length?'':'disabled'}>Confirmar recebimento</button></section></div>`}else if(state.adminView==='discord')content=`<section class="card"><h2>Configuração do Discord</h2><form id="settings" class="form"><label>Webhook<input name="discordWebhook" value="${esc(state.settings.discordWebhook||'')}"></label><div class="actions">${['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'].map((d,i)=>`<label><input type="checkbox" name="days" value="${i}" ${(state.settings.discordDays||[]).includes(i)?'checked':''}> ${d}</label>`).join('')}</div><label>Horário (24h)<input name="discordHour" type="time" value="${esc(state.settings.discordHour||'18:00')}" required></label><button>Salvar configuração</button><button class="secondary" type="button" id="test">Enviar teste</button></form></section>`;else content=`<section class="card"><h2>Relatório mensal de movimentações</h2><div class="row"><label>Mês<input id="month" type="month" value="${new Date().toISOString().slice(0,7)}"></label><button id="csv">Baixar CSV</button></div><div id="report"></div></section>`;layout('Administração',`<nav class="nav">${tabs.map(([id,n])=>`<button class="${state.adminView===id?'active':''}" data-admin="${id}">${n}</button>`).join('')}</nav>${content}`);document.querySelectorAll('[data-admin]').forEach(b=>b.onclick=()=>{state.adminView=b.dataset.admin;admin()});bindPublic();if(state.adminView==='relatorio'){report();document.querySelector('#month').onchange=report;document.querySelector('#csv').onclick=csv}if(state.adminView==='discord'){document.querySelector('#settings').onsubmit=saveSettings;document.querySelector('#test').onclick=async()=>{try{await api('/admin/test-discord',{method:'POST'});msg('Mensagem de teste enviada.')}catch(e){msg(e.message,true)}}}if(state.adminView==='receber')signature()}
function reportData(){const m=document.querySelector('#month').value;return state.receipts.filter(r=>new Date(r.receivedAt).toISOString().slice(0,7)===m).map(r=>({...r,pallets:r.palletIds.map(id=>state.pallets.find(p=>p.id===id)).filter(Boolean)}))}
function report(){const groups=reportData(),sum={};groups.flatMap(r=>r.pallets).forEach(p=>sum[p.product]=(sum[p.product]||0)+Number(p.quantity));document.querySelector('#report').innerHTML=`<div class="totals">${Object.entries(sum).map(([n,q])=>`<div class="total"><strong>${esc(n)}</strong><br>${fmt(q)} unidades</div>`).join('')||'<p class="small">Nenhuma movimentação no período.</p>'}</div><br><table><thead><tr><th>Data e hora</th><th>Paletes</th><th>Unidades</th><th>Assinatura</th><th></th></tr></thead><tbody>${groups.map(r=>`<tr><td>${date(r.receivedAt)}</td><td>${r.pallets.length}</td><td>${fmt(r.pallets.reduce((a,p)=>a+Number(p.quantity),0))}</td><td><img class="signature-open" data-id="${r.id}" src="${r.signature}" alt="Assinatura" style="width:90px;height:36px;object-fit:contain;border:1px solid #dbe3ec;border-radius:5px;cursor:pointer"></td><td><button class="secondary receipt-open" data-id="${r.id}">Ver recebimento</button></td></tr>`).join('')||'<tr><td colspan="5" class="small">Nenhuma movimentação.</td></tr>'}</tbody></table>`;document.querySelectorAll('.receipt-open,.signature-open').forEach(b=>b.onclick=()=>receiptDetail(b.dataset.id));return groups}
function receiptDetail(id){const r=state.receipts.find(x=>x.id===id),p=r.palletIds.map(i=>state.pallets.find(x=>x.id===i)).filter(Boolean),m=document.createElement('div');m.className='modal';m.innerHTML=`<div class="modal-card"><h2>Recebimento em lote</h2><p class="small">${date(r.receivedAt)} · ${p.length} paletes</p><img src="${r.signature}" alt="Assinatura" style="display:block;width:100%;height:180px;object-fit:contain;border:1px solid #dbe3ec;border-radius:8px"><h3 style="margin-top:1rem">Paletes recebidos</h3>${table(p)}<p><button class="secondary">Fechar</button></p></div>`;document.body.append(m);m.querySelector('button').onclick=()=>m.remove()}
function csv(){const rows=['Produto;OP;Quantidade;Pronto em;Recebido em',...reportData().flatMap(r=>r.pallets.map(p=>[p.product,p.op,p.quantity,date(p.readyAt),date(r.receivedAt)].map(x=>`"${String(x).replaceAll('"','""')}"`).join(';')))],a=document.createElement('a');a.href=URL.createObjectURL(new Blob([rows.join('\n')],{type:'text/csv;charset=utf-8'}));a.download='movimentacoes-melodia.csv';a.click()}
async function saveSettings(e){e.preventDefault();const f=new FormData(e.target),discordDays=f.getAll('days').map(Number),discordHour=f.get('discordHour');if(!/^([01]\d|2[0-3]):[0-5]\d$/.test(discordHour))return msg('Informe o horário no formato 24h.',true);try{await api('/admin/settings',{method:'POST',body:JSON.stringify({discordWebhook:f.get('discordWebhook'),discordDays,discordHour})});msg('Configuração salva.')}catch(x){msg(x.message,true)}}
function parse(code){const p=String(code).trim().split('|');if(p.length!==4)throw Error('QR inválido.');return{id:p[0]}}
async function register(code){try{const d=await api('/public/register',{method:'POST',body:JSON.stringify({code})});state.feedback={text:`Palete registrado com sucesso: ${d.pallet.product} · ${fmt(d.pallet.quantity)} unidades.`};load()}catch(e){msg(e.message,true)}}
function add(code){try{const p=parse(code),found=state.pallets.find(x=>x.id===p.id&&x.status==='PRONTO');if(!found)throw Error('Este palete não está pendente ou não existe.');if(state.batch.includes(p.id))throw Error('Palete já adicionado ao lote.');state.batch.push(p.id);state.feedback={text:`Palete adicionado ao recebimento: ${found.product} · ${fmt(found.quantity)} unidades.`};load()}catch(e){msg(e.message,true)}}
function bindPublic(){document.querySelectorAll('.camera').forEach(b=>b.onclick=()=>camera(b.dataset.mode));const r=document.querySelector('#register');if(r)r.onsubmit=e=>{e.preventDefault();register(new FormData(e.target).get('code'))};const b=document.querySelector('#batch');if(b)b.onsubmit=e=>{e.preventDefault();add(new FormData(e.target).get('code'))};document.querySelectorAll('.remove').forEach(b=>b.onclick=()=>{const p=state.pallets.find(x=>x.id===b.dataset.id);state.batch=state.batch.filter(i=>i!==b.dataset.id);state.feedback={text:`Palete removido do recebimento${p?`: ${p.product}`:''}.`};load()});document.querySelectorAll('.cancel').forEach(b=>b.onclick=async()=>{const reason=prompt('Motivo do cancelamento:');if(!reason)return;try{await api('/public/cancel',{method:'POST',body:JSON.stringify({id:b.dataset.id,reason})});state.feedback={text:'Palete cancelado com sucesso.'};load()}catch(e){msg(e.message,true)}})}
function signature(){const c=document.querySelector('#signature');if(!c)return;const x=c.getContext('2d');x.lineWidth=3;x.lineCap='round';let d=false,pos=e=>{const r=c.getBoundingClientRect();return{x:(e.clientX-r.left)*c.width/r.width,y:(e.clientY-r.top)*c.height/r.height}};c.onpointerdown=e=>{d=true;let p=pos(e);x.beginPath();x.moveTo(p.x,p.y)};c.onpointermove=e=>{if(!d)return;let p=pos(e);x.lineTo(p.x,p.y);x.stroke();c.dataset.signed='1'};c.onpointerup=c.onpointerleave=()=>d=false;document.querySelector('#clear').onclick=()=>{x.clearRect(0,0,c.width,c.height);delete c.dataset.signed};document.querySelector('#confirm').onclick=async()=>{if(!c.dataset.signed)return msg('Faça a assinatura antes de confirmar.',true);try{const total=state.batch.length;await api('/public/receipts',{method:'POST',body:JSON.stringify({ids:state.batch,signature:c.toDataURL()})});state.batch=[];state.feedback={text:`Recebimento registrado com sucesso: ${total} palete${total===1?'':'s'} confirmado${total===1?'':'s'}.`};load()}catch(e){msg(e.message,true)}}}
async function camera(mode){if(!navigator.mediaDevices?.getUserMedia||!window.BarcodeDetector)return msg('Use Chrome atualizado ou a contingência manual.',true);const m=document.createElement('div');m.className='modal';m.innerHTML=`<div class="modal-card"><h2>Ler QR Code</h2><video autoplay playsinline></video><p><button class="secondary">Cancelar</button></p></div>`;document.body.append(m);let s;const close=()=>{s?.getTracks().forEach(t=>t.stop());m.remove()};m.querySelector('button').onclick=close;try{s=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});const v=m.querySelector('video');v.srcObject=s;const q=new BarcodeDetector({formats:['qr_code']});const scan=async()=>{if(!m.isConnected)return;const a=await q.detect(v).catch(()=>[]);if(a[0]?.rawValue){close();mode==='register'?register(a[0].rawValue):add(a[0].rawValue);return}requestAnimationFrame(scan)};scan()}catch(e){close();msg('Não foi possível abrir a câmera.',true)}}
function partialCode(code){try{const p=parse(code),pal=state.pallets.find(x=>x.id===p.id&&x.status==='PRONTO');if(!pal)throw Error('Palete pendente não encontrado.');const q=Number(prompt(`Quantidade a retirar de ${pal.product} (disponível: ${pal.quantity}):`));if(!Number.isFinite(q)||q<=0)return;const reason=prompt('Motivo da retirada parcial:');if(!reason)return;api('/public/partials',{method:'POST',body:JSON.stringify({id:pal.id,quantity:q,reason})}).then(d=>{state.feedback={text:`${d.partial.quantity} unidades separadas. Saldo do palete: ${d.pallet.quantity}.`};load()}).catch(e=>msg(e.message,true))}catch(e){msg(e.message,true)}}
function logistics(){const pend=state.pallets.filter(p=>p.status==='PRONTO'),chosen=state.batch.map(i=>pend.find(p=>p.id===i)).filter(Boolean),av=(state.partials||[]).filter(p=>p.status==='PENDENTE'),selected=(state.batchPartials||[]);layout('Logística',`${cards()}<div class="grid"><section class="card span-7"><h2>Receber transferência em lote</h2><div class="scanner"><button class="accent camera" data-mode="batch">Ler QR Code</button></div><ul class="scanlist">${chosen.map(p=>`<li>${esc(p.product)} · ${fmt(p.quantity)} un.</li>`).join('')||'<li class="small">Nenhum palete adicionado.</li>'}</ul><h3>Unidades avulsas aguardando validação</h3>${av.map(p=>`<p>${esc(p.product)} · OP ${esc(p.op)} · ${fmt(p.quantity)} un. <button class="secondary receive-partial" data-id="${p.id}">${selected.includes(p.id)?'Adicionado':'Adicionar'}</button></p>`).join('')||'<p class="small">Nenhuma unidade avulsa pendente.</p>'}</section><section class="card span-5"><h2>Assinatura de recebimento</h2><canvas id="signature" width="700" height="280"></canvas><p><button class="secondary" id="clear">Limpar assinatura</button></p><button id="confirm" ${(chosen.length||selected.length)?'':'disabled'}>Confirmar recebimento</button></section></div>`);bindPublic();document.querySelectorAll('.receive-partial').forEach(b=>b.onclick=()=>{state.batchPartials=[...(state.batchPartials||[]),b.dataset.id];state.feedback={text:'Unidade avulsa adicionada ao recebimento.'};load()});signature()}
function signature(){const c=document.querySelector('#signature');if(!c)return;const x=c.getContext('2d');x.lineWidth=3;let d=false;c.onpointerdown=e=>{d=true;const r=c.getBoundingClientRect();x.beginPath();x.moveTo((e.clientX-r.left)*c.width/r.width,(e.clientY-r.top)*c.height/r.height)};c.onpointermove=e=>{if(!d)return;const r=c.getBoundingClientRect();x.lineTo((e.clientX-r.left)*c.width/r.width,(e.clientY-r.top)*c.height/r.height);x.stroke();c.dataset.signed='1'};c.onpointerup=c.onpointerleave=()=>d=false;document.querySelector('#clear').onclick=()=>{x.clearRect(0,0,c.width,c.height);delete c.dataset.signed};document.querySelector('#confirm').onclick=async()=>{if(!c.dataset.signed)return msg('Faça a assinatura antes de confirmar.',true);try{await api('/public/receipts',{method:'POST',body:JSON.stringify({ids:state.batch,partialIds:state.batchPartials||[],signature:c.toDataURL()})});state.batch=[];state.batchPartials=[];state.feedback={text:'Recebimento confirmado com sucesso.'};load()}catch(e){msg(e.message,true)}}}
function camera(mode){if(!navigator.mediaDevices?.getUserMedia||!window.BarcodeDetector)return msg('Use Chrome atualizado ou a contingência manual.',true);const m=document.createElement('div');m.className='modal';m.innerHTML=`<div class="modal-card"><h2>Ler QR Code</h2><video autoplay playsinline></video><p><button class="secondary">Cancelar</button></p></div>`;document.body.append(m);let s;const close=()=>{s?.getTracks().forEach(t=>t.stop());m.remove()};m.querySelector('button').onclick=close;navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false}).then(stream=>{s=stream;const v=m.querySelector('video');v.srcObject=s;const q=new BarcodeDetector({formats:['qr_code']});const scan=async()=>{if(!m.isConnected)return;const a=await q.detect(v).catch(()=>[]);if(a[0]?.rawValue){close();if(mode==='register')register(a[0].rawValue);else if(mode==='partial')partialCode(a[0].rawValue);else add(a[0].rawValue);return}requestAnimationFrame(scan)};scan()}).catch(()=>{close();msg('Não foi possível abrir a câmera.',true)})}
const nativeLogistics=logistics;
logistics=function(){nativeLogistics();const box=document.querySelector('.card.span-7');if(!box)return;const selected=state.batchPartials||[],pending=(state.partials||[]).filter(p=>p.status==='PENDENTE');box.insertAdjacentHTML('beforeend',`<hr><h3>Unidades avulsas em recebimento</h3>${selected.length?selected.map(id=>{const p=pending.find(x=>x.id===id);return p?`<p><span class="badge">AVULSO</span> ${esc(p.product)} · ${fmt(p.quantity)} un. <button class="secondary partial-remove" data-id="${p.id}">Retirar do recebimento</button></p>`:''}).join(''):'<p class="small">Nenhuma unidade avulsa adicionada.</p>'}<h3>Unidades avulsas disponíveis</h3>${pending.filter(p=>!selected.includes(p.id)).map(p=>`<p>${esc(p.product)} · OP ${esc(p.op)} · ${fmt(p.quantity)} un. <button class="secondary partial-add" data-id="${p.id}">Adicionar ao recebimento</button></p>`).join('')||'<p class="small">Nenhuma unidade avulsa disponível.</p>'}`);document.querySelectorAll('.partial-add').forEach(b=>b.onclick=()=>{state.batchPartials=[...(state.batchPartials||[]),b.dataset.id];state.feedback={text:'Unidade avulsa adicionada ao recebimento.'};load()});document.querySelectorAll('.partial-remove').forEach(b=>b.onclick=()=>{state.batchPartials=(state.batchPartials||[]).filter(id=>id!==b.dataset.id);state.feedback={text:'Unidade avulsa retirada do recebimento.'};load()})};
const nativeReport=report;
