document.head.insertAdjacentHTML('beforeend','<style>.camera-modal{width:min(94vw,440px);max-height:94dvh;overflow-y:auto}.camera-heading{display:flex;align-items:center;justify-content:space-between;gap:.8rem}.camera-heading h2{margin:0}.camera-cancel-top{white-space:nowrap}.camera-preview{position:relative;width:min(78vw,360px);aspect-ratio:1;margin:.7rem auto;background:#001834;border-radius:.8rem;overflow:hidden}.camera-preview video{width:100%;height:100%;object-fit:cover;display:block}.qr-guide{position:absolute;inset:13%;pointer-events:none}.qr-guide span{position:absolute;width:24%;height:24%;border-color:#fff;border-style:solid;filter:drop-shadow(0 1px 2px #001834)}.qr-guide .tl{top:0;left:0;border-width:4px 0 0 4px}.qr-guide .tr{top:0;right:0;border-width:4px 4px 0 0}.qr-guide .bl{bottom:0;left:0;border-width:0 0 4px 4px}.qr-guide .br{right:0;bottom:0;border-width:0 4px 4px 0}.camera-tools{display:grid;grid-template-columns:1fr 1fr;gap:.65rem;align-items:stretch;margin:.8rem 0}.camera-tools>button{width:100%;padding:.65rem .45rem}.camera-zoom{display:flex;flex-direction:column;justify-content:center;gap:.25rem;font-weight:600;min-width:0}.camera-zoom input{width:100%;accent-color:#ffcf3c}.camera-modal #camera-hint{margin:.35rem 0}.app-version{position:fixed;right:.9rem;bottom:.55rem;z-index:20;padding:.18rem .45rem;border-radius:.35rem;background:rgba(255,255,255,.88);color:#5f7187;font-size:.7rem;pointer-events:none;box-shadow:0 1px 5px rgba(0,24,52,.12)}@media(max-width:380px){.camera-preview{width:min(82vw,330px)}.camera-tools{gap:.45rem}.camera-tools>button{font-size:.82rem}}</style>');
cards=function(){const s=state.summary,cols=[];for(let i=0;i<s.products.length;i+=2)cols.push(s.products.slice(i,i+2));return `<section class="movement-summary"><div class="movement-title">AGUARDANDO TRANSFERÊNCIA</div><div class="movement-counts"><div class="movement-count"><strong>${s.pallets}</strong><span>PALLETS</span></div><div class="movement-count"><strong>${s.partials}</strong><span>AVULSOS</span></div></div><div class="product-scroll">${cols.map(c=>`<div class="product-column">${c.map(x=>`<div><strong>${esc(x.product)}</strong><small>${fmt(x.quantity)} unidades</small></div>`).join('')}</div>`).join('')||'<span class="small">Nenhum item aguardando transferência.</span>'}</div></section>`};
const returnPartial=async id=>{const item=(state.partials||[]).find(x=>x.id===id&&x.status==='PENDENTE');if(!item)return;const q=Number(prompt(`Quantidade a devolver ao palete original (disponível: ${item.quantity}):`));if(!Number.isFinite(q)||q<=0)return;try{const d=await api(`/public/partials/${encodeURIComponent(id)}/return`,{method:'POST',body:JSON.stringify({quantity:q})});state.feedback={text:`${d.returned} unidade${d.returned===1?'':'s'} devolvida${d.returned===1?'':'s'} ao palete original.`};load()}catch(e){msg(e.message,true)}};
function betaTabs(view,items,key){return `<nav class="nav beta-tabs">${items.map(([id,label])=>`<button class="${view===id?'active':''}" data-${key}="${id}">${label}</button>`).join('')}</nav>`}
function betaReceipt(manual=false){const pend=state.pallets.filter(p=>p.status==='PRONTO'),chosen=(state.batch||[]).map(id=>pend.find(p=>p.id===id)).filter(Boolean),av=(state.batchPartials||[]).map(id=>(state.partials||[]).find(p=>p.id===id&&p.status==='PENDENTE')).filter(Boolean);return `<div class="grid"><section class="card span-7"><h2>Receber paletes</h2><div class="scanner"><button class="accent camera" data-mode="batch">Ler QR Code</button>${manual?'<details><summary class="small">Inserir código manualmente</summary><form id="batch" class="form"><input name="code" required><button>Adicionar</button></form></details>':''}</div><ul class="scanlist">${chosen.map(p=>`<li>${esc(p.product)} · OP ${esc(p.op)} · ${fmt(p.quantity)} un.<button class="secondary remove" data-id="${esc(p.id)}">Remover</button></li>`).join('')||'<li class="small">Nenhum palete adicionado.</li>'}</ul><p class="batch-avulsos">${av.length?`<span class="badge received">${av.length} AVULSO${av.length===1?'':'S'}</span> adicionado${av.length===1?'':'s'} ao recebimento. Veja a aba Avulsos.`:'Nenhum avulso adicionado ao recebimento.'}</p></section><section class="card span-5"><label class="receipt-observation">Observação <textarea id="observation" rows="3" maxlength="600" placeholder="Opcional: informe qualquer observação sobre este recebimento."></textarea></label><h2>Assinatura de recebimento</h2><canvas id="signature" width="700" height="280"></canvas><div class="signature-actions"><button class="secondary" id="clear">Limpar assinatura</button><button id="confirm" disabled>Confirmar recebimento</button></div></section></div>`}
function betaWireReceipt(){bindPublic();const c=document.querySelector('#signature'),clear=document.querySelector('#clear'),confirm=document.querySelector('#confirm'),observation=document.querySelector('#observation');if(!c)return;const ctx=c.getContext('2d');ctx.lineWidth=3;ctx.lineCap='round';let drawing=false;const refresh=()=>confirm.disabled=!(c.dataset.signed&&((state.batch||[]).length+(state.batchPartials||[]).length));const pos=e=>{const r=c.getBoundingClientRect();return{x:(e.clientX-r.left)*c.width/r.width,y:(e.clientY-r.top)*c.height/r.height}};c.onpointerdown=e=>{drawing=true;const p=pos(e);ctx.beginPath();ctx.moveTo(p.x,p.y);c.dataset.signed='1';refresh()};c.onpointermove=e=>{if(!drawing)return;const p=pos(e);ctx.lineTo(p.x,p.y);ctx.stroke()};c.onpointerup=c.onpointerleave=()=>drawing=false;clear.onclick=()=>{ctx.clearRect(0,0,c.width,c.height);delete c.dataset.signed;refresh()};confirm.onclick=async()=>{if(confirm.disabled)return;try{await api('/public/receipts',{method:'POST',body:JSON.stringify({ids:state.batch,partialIds:state.batchPartials||[],observation:observation?.value||'',signature:c.toDataURL()})});state.batch=[];state.batchPartials=[];state.feedback={text:'Recebimento confirmado com sucesso.'};load()}catch(e){msg(e.message,true)}};refresh()}
production=function(){state.productionView=state.productionView||'pendentes';const tabs=betaTabs(state.productionView,[['pendentes','Pendentes'],['avulsos','Avulsos']],'production');let content='';if(state.productionView==='pendentes')content=`<div class="grid"><section class="card span-4"><h2>Registrar palete</h2><p class="small">Leia o QR Code da capa.</p><div class="scanner"><button class="accent camera" data-mode="register">Ler QR Code</button></div></section><section class="card span-8"><h2>Paletes pendentes</h2>${table(state.pallets.filter(p=>p.status==='PRONTO'),true)}</section></div>`;else{const av=(state.partials||[]).filter(p=>p.status==='PENDENTE');content=`<div class="grid"><section class="card span-4"><h2>Adicionar avulso</h2><p class="small">Leia o QR Code do palete de origem e informe a quantidade.</p><div class="scanner"><button class="accent camera" data-mode="partial">Ler QR Code</button></div></section><section class="card span-8"><h2>Avulsos aguardando transferência</h2>${av.length?`<ul class="scanlist">${av.map(p=>`<li><span class="badge received">AVULSO</span> ${esc(p.product)} · OP ${esc(p.op)} · ${fmt(p.quantity)} un.<button class="secondary return-partial" data-id="${p.id}">Devolver</button></li>`).join('')}</ul>`:'<p class="small">Nenhum avulso pendente.</p>'}</section></div>`}layout('Produção',`${cards()}${tabs}${content}`);document.querySelectorAll('[data-production]').forEach(b=>b.onclick=()=>{state.productionView=b.dataset.production;production()});bindPublic();document.querySelectorAll('.return-partial').forEach(b=>b.onclick=()=>returnPartial(b.dataset.id))};
