admin=function(){betaAdminBase();const nav=document.querySelector('.nav'),avTab=nav?.querySelector('[data-avulso]');if(avTab)avTab.textContent='Avulsos';if(state.adminView!=='avulso')return;const card=document.querySelector('.card');if(!card)return;const av=(state.partials||[]).filter(p=>p.status==='PENDENTE');card.innerHTML=`<h2>Avulsos</h2><p class="small">Leia o QR Code do palete de origem ou informe o código manualmente. Os avulsos podem ser devolvidos parcialmente ao palete.</p><div class="scanner"><button class="accent camera" data-mode="partial">Ler QR Code</button><details><summary class="small">Inserir código manualmente</summary><form id="partial-form" class="form"><input name="code" required><button>Continuar</button></form></details></div><h3>Avulsos pendentes</h3>${av.length?`<ul class="scanlist">${av.map(p=>`<li><span class="badge received">AVULSO</span> ${esc(p.product)} · OP ${esc(p.op)} · ${fmt(p.quantity)} un.<button class="secondary return-partial" data-id="${p.id}">Devolver</button></li>`).join('')}</ul>`:'<p class="small">Nenhum avulso pendente.</p>'}`;bindPublic();document.querySelector('#partial-form').onsubmit=e=>{e.preventDefault();partialCode(new FormData(e.target).get('code'))};document.querySelectorAll('.return-partial').forEach(b=>b.onclick=()=>returnPartial(b.dataset.id))};
const DEFAULT_LINES=[['BIOAVIS BITS','BIOAVIS BITS','#17341E'],['BIOAVIS MIX','BIOAVIS MIX','#2E2B62'],['M1X SEED','M1X SEED','#FFCD10'],['HPRO','HPRO','#E2752A'],['ZOOPRIME','ZOOPRIME','#2C2B26']];
