cards=function(){const s=state.summary,cols=[];for(let i=0;i<s.products.length;i+=2)cols.push(s.products.slice(i,i+2));return `<section class="movement-summary"><div class="movement-title">AGUARDANDO TRANSFERÊNCIA</div><div class="movement-counts"><div class="movement-count"><strong>${s.pallets}</strong><span>PALLETS</span></div><div class="movement-count"><strong>${s.partials}</strong><span>AVULSOS</span></div></div><div class="product-scroll">${cols.map(c=>`<div class="product-column">${c.map(x=>`<div class="line-product" style="--line:${productLine(x.product).color}"><strong>${esc(x.product)}</strong><small>${fmt(x.quantity)} unidades</small></div>`).join('')}</div>`).join('')||'<span class="small">Nenhum item aguardando transferência.</span>'}</div></section>`};
const reportGroups=()=>{const m=document.querySelector('#month')?.value||new Date().toISOString().slice(0,7);return state.receipts.filter(r=>r.receivedAt.slice(0,7)===m).map(r=>({...r,pallets:r.palletIds.map(id=>state.pallets.find(p=>p.id===id)).filter(Boolean),partials:(r.partialIds||[]).map(id=>(state.partials||[]).find(p=>p.id===id)).filter(Boolean)})).sort((a,b)=>new Date(a.receivedAt)-new Date(b.receivedAt))};
