report=function(){const groups=reportGroups(),sum={};groups.forEach(r=>[...r.pallets,...r.partials].forEach(x=>sum[x.product]=(sum[x.product]||0)+Number(x.quantity)));const pallets=groups.reduce((n,r)=>n+r.pallets.length,0),avulsos=groups.reduce((n,r)=>n+r.partials.length,0),units=Object.values(sum).reduce((n,x)=>n+x,0);const row=document.querySelector('#month')?.parentElement?.parentElement;if(row)row.innerHTML=`<label>Mês<input id="month" type="month" value="${document.querySelector('#month')?.value||new Date().toISOString().slice(0,7)}"></label><button class="accent" id="apply">Aplicar</button><button class="secondary" id="pdf">Gerar PDF</button><button class="secondary" id="csv">Baixar CSV</button>`;document.querySelector('#report').innerHTML=`<h3>Resumo de itens</h3><div class="product-scroll report-products">${Object.keys(sum).sort((a,b)=>a.localeCompare(b,'pt-BR')).map(n=>`<div class="line-product" style="--line:${productLine(n).color}"><strong>${esc(n)}</strong><small>${fmt(sum[n])} unidades</small></div>`).join('')||'<span class="small">Nenhuma movimentação.</span>'}</div><div class="report-totals"><div><strong>${groups.length}</strong><span>RECEBIMENTOS</span></div><div><strong>${pallets}</strong><span>PALETES</span></div><div><strong>${fmt(units)}</strong><span>UNIDADES</span></div><div><strong>${avulsos}</strong><span>AVULSOS</span></div></div><h3>Recebimentos</h3>${groups.map((r,i)=>`${receiptHead(r,i,state.openReceipt===r.id)}${state.openReceipt===r.id?receiptLists(r):''}`).join('')||'<p class="small">Nenhum recebimento.</p>'}`;document.querySelector('#apply').onclick=()=>{state.openReceipt=null;report()};document.querySelector('#csv').onclick=csv;document.querySelector('#pdf').onclick=()=>{const rows=groups.map((r,i)=>`<section class="print-receipt"><div><b class="receipt-number">${i+1}</b> ${date(r.receivedAt)} · ${r.pallets.length} paletes · ${fmt([...r.pallets,...r.partials].reduce((n,x)=>n+Number(x.quantity),0))} unidades</div>${receiptLists(r)}</section>`).join('');const w=window.open('','_blank');w.document.write(`<!doctype html><html><head><title>Relatório mensal</title><style>body{font:12px Arial;color:#001834;margin:28px}header{display:flex;align-items:center;gap:18px}header img{width:130px}.totals{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin:20px 0}.totals div{border:1px solid #dbe3ec;padding:12px;text-align:center}.totals strong{display:block;font-size:24px}.receipt-number{display:inline-block;background:#001834;color:#fff;padding:4px 8px;border-radius:4px}.print-receipt{border-top:1px solid #b8c5d3;padding:12px 0}.receipt-lists{display:grid;grid-template-columns:1fr 1fr;gap:30px}.receipt-lists h4{margin-bottom:4px}ul{margin-top:0;padding-left:16px}</style></head><body><header><img src="${location.origin}/melodia-logo.png"><h1>Relatório mensal — ${document.querySelector('#month').value}</h1></header><div class="totals"><div><strong>${groups.length}</strong>RECEBIMENTOS</div><div><strong>${pallets}</strong>PALETES</div><div><strong>${fmt(units)}</strong>UNIDADES</div><div><strong>${avulsos}</strong>AVULSOS</div></div>${rows}</body></html>`);w.document.close();w.onload=()=>w.print()};document.querySelectorAll('[data-receipt]').forEach(b=>b.onclick=()=>{state.openReceipt=state.openReceipt===b.dataset.receipt?null:b.dataset.receipt;report()})};
document.head.insertAdjacentHTML('beforeend','<style>.line-product{border-left:7px solid var(--line);padding-left:.5rem!important}.report-products{margin-bottom:1rem}.report-totals{display:grid;grid-template-columns:repeat(4,1fr);gap:.65rem;margin:1rem 0}.report-totals div{padding:.7rem;border:1px solid #dbe3ec;border-radius:.6rem;text-align:center}.report-totals strong{display:block;font-size:1.4rem;color:#001834}.report-totals span{font-size:.7rem;font-weight:800;color:#61758d}.receipt-row{width:100%;display:flex;align-items:center;gap:.55rem;text-align:left;margin-top:.45rem;background:#fff;border:1px solid #dbe3ec;color:#001834}.receipt-row span:nth-child(2){flex:1}.receipt-row img{width:56px;height:25px;object-fit:contain}.receipt-number{display:inline-flex;align-items:center;justify-content:center;min-width:1.5rem;height:1.5rem;border-radius:.3rem;background:#001834;color:#fff;font-weight:800}.receipt-lists{display:grid;grid-template-columns:1fr 1fr;gap:1rem;padding:.65rem 1rem;border:1px solid #dbe3ec;border-top:0}.receipt-lists h4{margin:.2rem 0}.receipt-lists ul{margin:.2rem 0;padding-left:1rem}@media(max-width:600px){.report-totals{grid-template-columns:1fr 1fr}.receipt-row{font-size:.78rem}.receipt-lists{gap:.5rem}}</style>');
/* Beta 4: relatório e configurações administrativas. */
const monthLong=month=>new Intl.DateTimeFormat('pt-BR',{month:'long',year:'numeric'}).format(new Date(`${month}-01T12:00:00`)).replace(/^./,letter=>letter.toUpperCase());
const lineCard=(name,quantity)=>`<div class="line-product" style="--line:${productLine(name).color}"><strong>${esc(name)}</strong><small>${fmt(quantity)} unidades</small></div>`;
const productSummaryCards=sum=>{
  const names=Object.keys(sum).sort((a,b)=>a.localeCompare(b,'pt-BR'));
  const columns=[];
  for(let index=0;index<names.length;index+=2)columns.push(names.slice(index,index+2));
  return `<div class="product-scroll report-products">${columns.map(column=>`<div class="product-column">${column.map(name=>lineCard(name,sum[name])).join('')}</div>`).join('')||'<span class="small">Nenhuma movimentação.</span>'}</div>`;
};
const receiptUnits=receipt=>[...receipt.pallets,...receipt.partials].reduce((total,item)=>total+Number(item.quantity||0),0);
const receiptTags=receipt=>`${receipt.pallets.length?'<span class="receipt-tag pallet-tag">PALETE</span>':''}${receipt.partials.length?'<span class="receipt-tag partial-tag">AVULSO</span>':''}`;
const receiptExpanded=(receipt,expanded=false)=>{
  const makeList=(items,empty)=>items.length?`<ul>${[...items].sort((a,b)=>a.product.localeCompare(b.product,'pt-BR')).map(item=>`<li>${esc(item.product)} · ${fmt(item.quantity)} un.</li>`).join('')}</ul>`:`<p class="small">${empty}</p>`;
  return `<div class="receipt-detail"><div><h4>PALETES <span>${receipt.pallets.length}</span></h4>${makeList(receipt.pallets,'Nenhum palete.')}</div><div><h4>AVULSOS <span>${receipt.partials.length}</span></h4>${makeList(receipt.partials,'Nenhum avulso.')}</div>${receipt.observation?`<div class="receipt-observation-report"><span>OBSERVAÇÃO</span><p>${esc(receipt.observation)}</p></div>`:''}${expanded&&receipt.signature?`<div class="receipt-signature-large"><span>ASSINATURA DE RECEBIMENTO</span><img src="${receipt.signature}" alt="Assinatura de recebimento"></div>`:''}</div>`;
};
const receiptHeader=(receipt,index,open)=>`<button class="receipt-row" type="button" data-receipt="${receipt.id}" aria-expanded="${open}"><span class="receipt-number">${index+1}</span><span class="receipt-main">${date(receipt.receivedAt)} <span class="receipt-tags">${receiptTags(receipt)}</span> · ${receipt.pallets.length} paletes · ${fmt(receiptUnits(receipt))} unidades</span>${receipt.signature?`<span class="receipt-signature"><img src="${receipt.signature}" alt="Assinatura"></span>`:''}<b class="receipt-arrow">${open?'⌃':'⌄'}</b></button>`;
csv=function(){
  const rows=['Tipo;Produto;OP;Quantidade;Data/hora do recebimento'];
  reportGroups().forEach(receipt=>{
    receipt.pallets.forEach(item=>rows.push(['Palete',item.product,item.op,item.quantity,date(receipt.receivedAt)].map(value=>`"${String(value).replaceAll('"','""')}"`).join(';')));
    receipt.partials.forEach(item=>rows.push(['Avulso',item.product,item.op,item.quantity,date(receipt.receivedAt)].map(value=>`"${String(value).replaceAll('"','""')}"`).join(';')));
  });
  const link=document.createElement('a');
  link.href=URL.createObjectURL(new Blob([rows.join('\n')],{type:'text/csv;charset=utf-8'}));
  link.download='movimentacoes-melodia.csv';
  link.click();
};
report=function(){
  const groups=reportGroups();
  const totalsByProduct={};
  groups.forEach(receipt=>[...receipt.pallets,...receipt.partials].forEach(item=>{totalsByProduct[item.product]=(totalsByProduct[item.product]||0)+Number(item.quantity||0)}));
  const pallets=groups.reduce((total,receipt)=>total+receipt.pallets.length,0);
  const avulsos=groups.reduce((total,receipt)=>total+receipt.partials.length,0);
  const units=Object.values(totalsByProduct).reduce((total,value)=>total+value,0);
  const activeMonth=document.querySelector('#month')?.value||new Date().toISOString().slice(0,7);
  const controls=document.querySelector('#report-controls');
  if(controls)controls.innerHTML=`<label>Mês<input id="month" type="month" value="${activeMonth}"></label><button class="accent" id="apply" type="button">Aplicar</button><button class="report-action" id="pdf" type="button">Gerar PDF</button><button class="report-action" id="csv" type="button">Baixar CSV</button>`;
  document.querySelector('#report').innerHTML=`<h3>Resumo de itens</h3>${productSummaryCards(totalsByProduct)}<div class="report-totals"><div><strong>${groups.length}</strong><span>RECEBIMENTOS</span></div><div><strong>${fmt(units)}</strong><span>UNIDADES</span></div><div><strong>${pallets}</strong><span>PALETES</span></div><div><strong>${avulsos}</strong><span>AVULSOS</span></div></div><h3>Recebimentos</h3><div class="receipt-history">${groups.map((receipt,index)=>`${receiptHeader(receipt,index,state.openReceipt===receipt.id)}${state.openReceipt===receipt.id?receiptExpanded(receipt,true):''}`).join('')||'<p class="small">Nenhum recebimento neste mês.</p>'}</div>`;
  document.querySelector('#apply').onclick=()=>{state.openReceipt=null;load()};
  document.querySelector('#csv').onclick=csv;
  document.querySelector('#pdf').onclick=()=>{
    const printRows=groups.map((receipt,index)=>`<section class="print-receipt"><div class="print-receipt-title"><b class="receipt-number">${index+1}</b><strong>${date(receipt.receivedAt)} · ${receipt.pallets.length} paletes · ${fmt(receiptUnits(receipt))} unidades</strong></div>${receiptExpanded(receipt,false)}</section>`).join('')||'<p>Nenhum recebimento neste mês.</p>';
    const generatedAt=new Date().toLocaleString('pt-BR');
    const printWindow=window.open('','_blank');
    printWindow.document.write(`<!doctype html><html lang="pt-BR"><head><title>Relatório Mensal - ${monthLong(activeMonth)}</title><style>@page{size:A4 portrait;margin:15mm}body{font:12px Arial,sans-serif;color:#001834;margin:0}header{display:flex;align-items:center;gap:16px;border-bottom:2px solid #ffcd10;padding-bottom:12px}header img{width:125px;height:auto}.print-header-content{flex:1}h1{font-size:21px;margin:0}.print-meta{margin:.3rem 0 0;font-size:9px;color:#61758d}.print-totals{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin:18px 0}.print-totals div{border:1px solid #d7e0e9;border-radius:6px;text-align:center;padding:10px}.print-totals strong{display:block;font-size:22px;margin-bottom:4px}.print-totals span{font-size:9px;font-weight:bold;color:#61758d}.section-title{font-size:13px;font-weight:bold;letter-spacing:.04em;border-bottom:1px solid #b8c5d3;padding-bottom:6px;margin:22px 0 0}.print-receipt{padding:12px 0;border-bottom:1px solid #d7e0e9;break-inside:avoid}.print-receipt-title{display:flex;align-items:center;gap:8px}.receipt-number{display:inline-flex;align-items:center;justify-content:center;min-width:20px;height:20px;border-radius:4px;background:#001834;color:#fff}.receipt-detail{display:grid;grid-template-columns:1fr 1fr;gap:26px;margin:9px 0 0 28px}.receipt-detail h4{margin:0 0 4px;font-size:10px}.receipt-detail h4 span{background:#ffcd10;border-radius:9px;padding:1px 5px}.receipt-detail ul{margin:0;padding-left:14px}.receipt-detail li{margin:2px 0}.receipt-signature-large{display:none}</style></head><body><header><img src="${location.origin}/melodia-logo.png" alt="Melodia Pet"><div class="print-header-content"><h1>Relatório Mensal - ${monthLong(activeMonth)}</h1><p class="print-meta">Gerado em ${generatedAt} · ${SYSTEM_VERSION}</p></div></header><div class="print-totals"><div><strong>${groups.length}</strong><span>RECEBIMENTOS</span></div><div><strong>${fmt(units)}</strong><span>UNIDADES</span></div><div><strong>${pallets}</strong><span>PALETES</span></div><div><strong>${avulsos}</strong><span>AVULSOS</span></div></div><div class="section-title">DETALHAMENTO DOS RECEBIMENTOS</div>${printRows}</body></html>`);
    printWindow.document.close();
    printWindow.onload=()=>printWindow.print();
  };
  document.querySelectorAll('[data-receipt]').forEach(button=>button.onclick=()=>{state.openReceipt=state.openReceipt===button.dataset.receipt?null:button.dataset.receipt;report()});
};
const configLine=(line={name:'',match:'',color:'#001834'})=>`<div class="config-line"><input data-line="name" value="${esc(line.name)}" placeholder="Ex.: M1X SEED" aria-label="Nome da linha" required><input data-line="match" value="${esc(line.match)}" placeholder="Texto presente no produto" aria-label="Texto identificador" required><span class="color-field"><input data-line="color" type="color" value="${esc(line.color||'#001834')}" title="Selecionar cor"><input data-line="hex" class="hex-input" value="${esc(line.color||'#001834')}" inputmode="text" maxlength="7" aria-label="Código hexadecimal da cor"></span><button type="button" class="secondary line-remove">Remover</button></div>`;
const changelog=`<section class="settings-section changelog"><h3>Changelog</h3><div class="changelog-grid"><article><h4>v1.1.6 <span>Atual</span></h4><b>Melhorias</b><ul><li>Admin passa a ter instalação própria como aplicativo no celular.</li></ul><b>Correções de bugs</b><ul><li>Atalho instalado do Admin abre diretamente em /admin.</li></ul></article><article><h4>v1.1.5</h4><b>Melhorias</b><ul><li>Organização visual aprimorada na tela de acesso e nas Configurações.</li></ul><b>Correções de bugs</b><ul><li>Checkbox de acesso persistente alinhado ao seu texto.</li></ul></article><article><h4>v1.1.4</h4><b>Melhorias</b><ul><li>Opção para manter o acesso administrativo neste dispositivo.</li><li>Botão Sair disponível no cabeçalho do Admin.</li></ul><b>Correções de bugs</b><ul><li>Paletas das abas e cores dos botões do relatório corrigidas.</li></ul></article></div><p class="changelog-note small">Versões seguem o padrão <b>vMAIOR.MENOR.CORREÇÃO</b>: correções de bugs alteram a última casa; novas melhorias relevantes, a casa do meio; e mudanças grandes de funcionamento, a primeira.</p></section>`;
const configurationView=()=>`<section class="card settings-page"><h2>Configurações</h2><form id="settings" class="form"><section class="settings-section"><h3>Discord</h3><div class="discord-webhook"><label>Webhook do canal Discord<input name="discordWebhook" value="${esc(state.settings.discordWebhook||'')}" placeholder="https://discord.com/api/webhooks/..." ></label><button type="button" class="secondary" id="test">Enviar teste</button></div><div class="discord-schedule"><div class="schedule-days"><label>Dias de envio</label><div class="weekdays">${['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'].map((day,index)=>`<label><input type="checkbox" name="days" value="${index}" ${(state.settings.discordDays||[]).includes(index)?'checked':''}><span>${day}</span></label>`).join('')}</div></div><label>Horário (24h)<input name="discordHour" type="time" value="${esc(state.settings.discordHour||'18:00')}" required></label></div></section><section class="settings-section"><h3>Linhas de produto</h3><p class="small line-description">O sistema identifica a linha quando o nome do produto contém o texto informado.</p><label class="default-color">Cor padrão <span class="small">Usada quando o produto não atender a nenhuma regra.</span><span><input id="default-color-picker" type="color" value="${esc(state.settings.defaultProductColor||'#001834')}" title="Selecionar cor padrão"><input id="default-color-hex" class="hex-input" value="${esc(state.settings.defaultProductColor||'#001834')}" inputmode="text" maxlength="7" aria-label="Código hexadecimal da cor padrão"></span></label><div class="config-line-header"><span>Nome da linha</span><span>Texto identificador</span><span>Cor</span><span></span></div><div id="product-lines">${(state.settings.productLines||DEFAULT_LINES.map(([name,match,color])=>({name,match,color}))).map(configLine).join('')}</div><button type="button" class="secondary" id="line-add">Adicionar linha</button></section><div class="actions settings-save"><button class="accent">Salvar configurações</button></div></form></section>${changelog}`;
const wireConfiguration=()=>{
  const lines=document.querySelector('#product-lines');
  const normalizeHex=value=>/^#[0-9a-f]{6}$/i.test(value.trim())?value.trim().toUpperCase():null;
  const bindColor=scope=>scope.querySelectorAll('.config-line').forEach(row=>{const picker=row.querySelector('[data-line="color"]'),hex=row.querySelector('[data-line="hex"]');picker.oninput=()=>hex.value=picker.value.toUpperCase();hex.onchange=()=>{const value=normalizeHex(hex.value);if(value){picker.value=value;hex.value=value}else hex.value=picker.value.toUpperCase()}});
  const bindRemove=scope=>scope.querySelectorAll('.line-remove').forEach(button=>button.onclick=()=>button.closest('.config-line').remove());
  bindRemove(lines);
  bindColor(lines);
  const defaultPicker=document.querySelector('#default-color-picker'),defaultHex=document.querySelector('#default-color-hex');
  defaultPicker.oninput=()=>defaultHex.value=defaultPicker.value.toUpperCase();
  defaultHex.onchange=()=>{const value=normalizeHex(defaultHex.value);if(value){defaultPicker.value=value;defaultHex.value=value}else defaultHex.value=defaultPicker.value.toUpperCase()};
  document.querySelector('#line-add').onclick=()=>{lines.insertAdjacentHTML('beforeend',configLine());bindRemove(lines);bindColor(lines)};
  document.querySelector('#settings').onsubmit=async event=>{
    event.preventDefault();
    const form=new FormData(event.target),discordHour=form.get('discordHour');
    if(!/^([01]\d|2[0-3]):[0-5]\d$/.test(discordHour))return msg('Informe o horário no formato 24h.',true);
    const productLines=[...lines.querySelectorAll('.config-line')].map(row=>({name:row.querySelector('[data-line="name"]').value.trim(),match:row.querySelector('[data-line="match"]').value.trim(),color:row.querySelector('[data-line="color"]').value})).filter(line=>line.name&&line.match);
    try{await api('/admin/settings',{method:'POST',body:JSON.stringify({discordWebhook:form.get('discordWebhook'),discordDays:form.getAll('days').map(Number),discordHour,defaultProductColor:defaultPicker.value,productLines})});state.feedback={text:'Configurações salvas com sucesso.'};load()}catch(error){msg(error.message,true)}
  };
  document.querySelector('#test').onclick=async()=>{try{await api('/admin/test-discord',{method:'POST'});msg('Mensagem de teste enviada.')}catch(error){msg(error.message,true)}};
};
admin=function(){
  state.adminView=state.adminView||'relatorio';
  const tabs=[['relatorio','Relatório'],['registrar','Registrar palete'],['pendentes','Pendentes'],['avulso','Avulsos'],['receber','Receber transferência'],['configuracoes','Configurações']];
  let content='';
  if(state.adminView==='registrar')content=`<section class="card"><h2>Registrar palete</h2><div class="scanner"><button class="accent camera" data-mode="register">Ler QR Code</button><details><summary class="small">Inserir código manualmente</summary><form id="register" class="form"><input name="code" required><button>Registrar palete</button></form></details></div></section>`;
  else if(state.adminView==='pendentes')content=`<section class="card"><h2>Paletes pendentes</h2>${table(state.pallets.filter(pallet=>pallet.status==='PRONTO'),true)}</section>`;
  else if(state.adminView==='avulso'){const av=(state.partials||[]).filter(item=>item.status==='PENDENTE'),selected=state.batchPartials||[];content=`<section class="card"><h2>Avulsos</h2><p class="small">Leia o QR Code do palete de origem ou informe o código manualmente. Os avulsos adicionados abaixo serão confirmados com a assinatura na aba Receber transferência.</p><div class="scanner"><button class="accent camera" data-mode="partial">Ler QR Code</button><details><summary class="small">Inserir código manualmente</summary><form id="partial-form" class="form"><input name="code" required><button>Continuar</button></form></details></div><h3>Avulsos no recebimento em andamento</h3>${selected.map(id=>{const item=av.find(partial=>partial.id===id);return item?`<p><span class="badge received">AVULSO</span> ${esc(item.product)} · OP ${esc(item.op)} · ${fmt(item.quantity)} un. <button class="secondary admin-av-remove" data-id="${item.id}">Retirar do recebimento</button></p>`:''}).join('')||'<p class="small">Nenhum avulso adicionado ao recebimento.</p>'}<h3>Avulsos pendentes</h3>${av.length?`<ul class="scanlist">${av.map(item=>`<li><span class="badge received">AVULSO</span> ${esc(item.product)} · OP ${esc(item.op)} · ${fmt(item.quantity)} un.<button class="secondary admin-av-add" data-id="${item.id}" ${selected.includes(item.id)?'disabled':''}>${selected.includes(item.id)?'Adicionado':'Adicionar ao recebimento'}</button><button class="secondary return-partial" data-id="${item.id}">Devolver</button></li>`).join('')}</ul>`:'<p class="small">Nenhum avulso pendente.</p>'}</section>`}
  else if(state.adminView==='receber')content=betaReceipt(true);
  else if(state.adminView==='configuracoes')content=configurationView();
  else content=`<section class="card"><h2>Relatório mensal de movimentações</h2><div class="row report-controls" id="report-controls"></div><div id="report"></div></section>`;
  const tabTone=id=>['registrar','pendentes','avulso'].includes(id)?'tab-production':id==='receber'?'tab-logistics':'tab-admin';
  layout('Administração',`<nav class="nav admin-nav">${tabs.map(([id,name])=>`<button class="${tabTone(id)} ${state.adminView===id?'active':''}" data-admin="${id}">${name}</button>`).join('')}</nav>${content}`);
  document.querySelectorAll('[data-admin]').forEach(button=>button.onclick=()=>{state.adminView=button.dataset.admin;admin()});
  bindPublic();
  if(state.adminView==='relatorio')report();
  if(state.adminView==='receber')betaWireReceipt();
  if(state.adminView==='configuracoes')wireConfiguration();
  if(state.adminView==='avulso'){document.querySelector('#partial-form').onsubmit=event=>{event.preventDefault();partialCode(new FormData(event.target).get('code'))};document.querySelectorAll('.return-partial').forEach(button=>button.onclick=()=>returnPartial(button.dataset.id));document.querySelectorAll('.admin-av-add').forEach(button=>button.onclick=()=>{state.batchPartials=[...(state.batchPartials||[]),button.dataset.id];state.feedback={text:'Avulso adicionado ao recebimento em andamento.'};admin()});document.querySelectorAll('.admin-av-remove').forEach(button=>button.onclick=()=>{state.batchPartials=(state.batchPartials||[]).filter(id=>id!==button.dataset.id);state.feedback={text:'Avulso retirado do recebimento em andamento.'};admin()})}
};
