layout=function(title,content){
  const feedback=state.feedback;state.feedback=null;
  const area=route==='/producao'?'production-area':route==='/logistica'?'logistics-area':'admin-area';
  const label=area==='production-area'?'PRODUÇÃO':area==='logistics-area'?'LOGÍSTICA':'ADMIN';
  app.innerHTML=`<div class="shell ${area}"><header class="top"><div class="brand-wrap"><img class="brand-logo" src="/melodia-logo.png" alt="Melodia Pet"><div><div class="brand-title">Controle de Movimentação</div><div class="area-label">${label}</div></div></div>${route==='/admin'&&state.token?'<button type="button" class="secondary admin-logout" id="admin-logout">Sair</button>':''}</header><div id="message">${feedback?`<div class="notice ${feedback.error?'error':''}">${esc(feedback.text)}</div>`:''}</div>${content}</div><footer class="app-version">Controle de Movimentação Melodia Pet · ${SYSTEM_VERSION}</footer>`;
  document.querySelector('#admin-logout')?.addEventListener('click',()=>{sessionStorage.removeItem('adminToken');localStorage.removeItem('adminToken');state.token='';state.batch=[];state.batchPartials=[];state.openReceipt=null;adminLogin()});
};
