adminLogin=function(){
  layout('Administração',`<section class="login"><h1>Acesso administrativo</h1><p class="small">Use a senha administrativa para consultar o relatório e configurar o sistema.</p><form id="adminlogin"><label>Senha<input type="password" name="password" required autofocus></label><label class="remember-login"><input type="checkbox" name="remember"> <span>Manter conectado neste dispositivo</span></label><div class="login-actions"><button>Entrar</button><button type="button" class="secondary" id="toggle-password">Mostrar senha</button></div></form></section>`);
  const form=document.querySelector('#adminlogin'),input=form.querySelector('[name=password]'),toggle=document.querySelector('#toggle-password');
  toggle.onclick=()=>{input.type=input.type==='password'?'text':'password';toggle.textContent=input.type==='password'?'Mostrar senha':'Ocultar senha'};
  form.onsubmit=async event=>{event.preventDefault();try{const data=await api('/login',{method:'POST',body:JSON.stringify({username:'admin',password:new FormData(form).get('password')})});state.token=data.token;if(form.querySelector('[name=remember]').checked){localStorage.adminToken=data.token;sessionStorage.removeItem('adminToken')}else{sessionStorage.adminToken=data.token;localStorage.removeItem('adminToken')}load()}catch(error){msg(error.message,true)}};
};
load();
